type Scene struct{ /* immutable snapshot */ }

var current atomic.Pointer[Scene]

func Publish() {
    next := &Scene{ /* built from the previous frame */ }
    current.Store(next)          // Swap(next) also returns the old frame
}

func Snapshot() *Scene { return current.Load() }

type Pair struct {
    mu      sync.RWMutex
    current *Scene
    next    *Scene
}

func (p *Pair) Publish() {
    p.mu.Lock()
    p.current, p.next = p.next, p.current   // the swap
    p.mu.Unlock()
}
func (p *Pair) View() *Scene { p.mu.RLock(); defer p.mu.RUnlock(); return p.current }
